import {uiText,uiJoin,isUiText,uiHTML,htmlDisplay,htmlOption,renderUI,mountLanguageControl,initializeLanguage,getLanguage,setLanguage} from '/locale.mjs';
/* Whole operator for the original ATSSC questionnaire workspace. */
const root=document.querySelector("#app");
const ui={tab:"case",state:null,native:null,session:null,notice:"",error:null,pending:null,busy:false,drafts:{},pages:{},source:null,sourcePreview:null,mapped:null,coverage:null,contactSource:null,contactChoices:{},selectedAssignment:null,selectedMessage:null,messagePreview:null,delivery:null,followups:null,history:null,template:null};
const tabs=[["case",uiText("Case")],["sources",uiText("Original sources")],["coverage",uiText("Coverage")],["contacts",uiText("Companies and contacts")],["assignments",uiText("Assignments")],["messages",uiText("Communications")],["followups",uiText("Follow-ups")],["exports",uiText("Export and history")]];
const h=v=>isUiText(v)?htmlDisplay(v):String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const j=v=>JSON.stringify(v,null,2);
const id=()=>crypto.randomUUID();
const stamp=()=>new Date().toISOString();
const bool=v=>v==="on"||v===true;
const dollars=v=>h(v??"");
const list=v=>String(v||"").split(/[\n,]/).map(x=>x.trim()).filter(Boolean);
function json(v,otherwise={}){if(!String(v||"").trim())return otherwise;try{return JSON.parse(v);}catch{throw Error(uiText("Enter complete valid JSON in the advanced field."));}}
function errorText(e){return e?.message||String(e);}
const CODE_LABELS=new Set(['TRADE','CONTACTS','PERSON','GENERIC_INBOX','PUBLIC_ENTRY','CREATE','UPDATE','KEEP_EXISTING','SKIP','KEEP_CURRENT','REPLACE','PHONE','EMAIL','POSTAL','IN_PERSON','REFERRAL','CONTACTED','NO_ANSWER','ASSISTANCE','CONTACT_CORRECTION','EXPECTED_RESPONSE','POSTAL_SENT','REFERRED','DECLINED','INVITATION','REMINDER','SUBMISSION_CONFIRMATION','STAFF_NOTIFICATION','REVISION_REQUEST','REVIEWED_COMPANY','NEW_COMPANY_CONTACT_REVIEW','company','contact','assignment','coverage','source','message','delivery_source','followup','profile','template','public_link']);
function opt(items,value,empty){return(empty===undefined?"":'<option value=""'+htmlOption(empty)+'>'+h(isUiText(empty)?renderUI(empty):empty)+'</option>')+items.map(x=>{const v=typeof x==="string"?x:x.value,l=typeof x==="string"?x:x.label;const label=typeof x==='string'&&CODE_LABELS.has(x)?uiText(l):l;return'<option value="'+h(v)+'"'+(String(v)===String(value)?" selected":"")+htmlOption(label)+'>'+h(isUiText(label)?renderUI(label):label)+'</option>';}).join("");}
function field(label,name,value="",type="text",extra=""){return'<label>'+h(label)+'<input type="'+type+'" name="'+h(name)+'" value="'+h(value)+'" '+extra+'></label>';}
function area(label,name,value="",extra=""){return'<label class="wide">'+h(label)+'<textarea name="'+h(name)+'" '+extra+'>'+h(value)+'</textarea></label>';}
function select(label,name,items,value,empty){return'<label>'+h(label)+'<select name="'+h(name)+'">'+opt(items,value,empty)+'</select></label>';}
function check(label,name,value=false,extra=""){return'<label class="check"><input type="checkbox" name="'+h(name)+'"'+(value?" checked":"")+" "+extra+'>'+h(label)+'</label>';}
function button(label,action,key="",extra=""){return'<button type="button" data-action="'+action+'" data-id="'+h(key)+'" '+extra+'>'+h(label)+'</button>';}
function submit(label){return'<button type="submit">'+h(label)+'</button>';}
function summary(label,value){return'<div class="stat"><span>'+h(label)+'</span><strong>'+h(value)+'</strong></div>';}
function empty(text){return'<p class="empty">'+h(text)+'</p>';}
function details(label,value){return'<details><summary>'+h(label)+'</summary><pre>'+h(j(value))+'</pre></details>';}
function downloads(links){return'<div class="actions">'+links.map(([label,url])=>'<a class="button" href="'+h(url)+'">'+h(label)+'</a>').join("")+'</div>';}
function form(name,contents,mutation=true){return'<form data-form="'+name+'"'+(mutation?' data-mutation="true"':"")+'><fieldset'+(ui.pending&&mutation?' disabled':"")+'><div class="form-grid">'+contents+'</div></fieldset></form>';}
function pageTable(key,headers,rows,rowFn){const size=50,total=rows.length,max=Math.max(0,Math.ceil(total/size)-1),page=Math.min(ui.pages[key]||0,max);ui.pages[key]=page;return'<div class="table-wrap"><table><thead><tr>'+headers.map(x=>'<th>'+h(x)+'</th>').join("")+'</tr></thead><tbody>'+rows.slice(page*size,(page+1)*size).map(rowFn).join("")+'</tbody></table></div><div class="pager"><span>'+h((total?uiJoin([String(page*size+1),"–",Math.min(total,(page+1)*size),uiText(" of "),total]):uiText("0 rows")))+'</span>'+button(uiText("Previous"),"page",key+"|"+(page-1),page<=0?"disabled":"")+button(uiText("Next"),"page",key+"|"+(page+1),page>=max?"disabled":"")+'</div>';}
function rowsJSON(rows){return pageTable("raw",[uiText("Original row"),uiText("Values and interpretation"),uiText("Issues")],rows,r=>'<tr><td>'+h(r.source?.row_number||r.row_number||r.id)+'</td><td>'+details(r.company_name||r.company_id||"Original values",r)+'</td><td>'+h([...(r.errors||[]),...(r.warnings||[])].map(x=>x.message||x.code).join("; "))+'</td></tr>');}
function sourceOptions(kind){return(ui.state.sources||[]).filter(x=>!kind||x.kind===kind).map(x=>({value:x.id,label:uiJoin([x.name,x.current?'':uiText(' · earlier edition')])}));}
function companyOptions(){return ui.state.companies.map(x=>({value:x.id,label:x.name+" ["+x.id+"]"}));}
function publicationOptions(){return(ui.native.publications||[]).map(x=>({value:x.id,label:uiJoin([(ui.native.questionnaires.find(q=>q.id===x.questionnaire_id)?.name||x.questionnaire_id),uiText(' · definition '),x.definition_version])}));}
function assignmentOptions(){return ui.state.assignments.map(x=>({value:x.id,label:x.company.name+" · "+x.contact.language+" · "+x.respondent.status}));}
function templateOptions(){return ui.state.templates.map(x=>({value:x.id,label:x.name+" · "+x.language+" · "+x.kind}));}
function pendingKey(){return"atssc-outreach:"+ui.state.workspace_id;}
function keepPending(){try{sessionStorage.setItem(pendingKey(),JSON.stringify(ui.pending));ui.pendingSaved=true;}catch{sessionStorage.setItem(pendingKey(),JSON.stringify({method:ui.pending.method,params:{request_id:ui.pending.params.request_id,id:ui.pending.params.id},bodyMissing:true}));ui.pendingSaved=false;}}
function clearPending(){ui.pending=null;sessionStorage.removeItem(pendingKey());}
async function request(path,body){let r;try{r=await fetch(path,{method:body===undefined?"GET":"POST",credentials:"same-origin",headers:body===undefined?{}:{"Content-Type":"application/json"},body:body===undefined?undefined:JSON.stringify(body)});}catch(e){e.uncertain=true;throw e;}let data;try{data=await r.json();}catch{const e=Error(uiText("The application response could not be read. Recover the original operation before retrying."));e.uncertain=true;throw e;}if(!r.ok||data.error){const raw=data.error,err=Error(typeof raw==="string"?raw:raw?.message||"The application rejected this operation.");err.code=raw?.code;err.detail=raw?.detail;err.status=r.status;err.definitive=r.status>=400&&r.status<500&&!["WORKSPACE_COMMIT_UNKNOWN","COMMIT_UNKNOWN","COMMIT_UNCERTAIN"].includes(err.code);throw err;}return data;}
async function call(method,params={}){return(await request("/api/invoke",{method:method.startsWith("outreach.")?method:"outreach."+method,params})).result;}
async function native(method,params={}){return(await request("/api/invoke",{method,params})).result;}
async function refresh(){const [state,nativeState]=await Promise.all([call("status"),native("status")]);ui.state=state;ui.native=nativeState;render();}
async function mutate(method,params,options={}){if(ui.pending)throw Error(uiText("Recover the retained operation before starting another change."));const actor=document.querySelector("#actor")?.value.trim()||sessionStorage.getItem("atssc-operator")||"",reason=options.reason||document.querySelector("#reason")?.value.trim()||"";if(!actor||!reason)throw Error(uiText("Enter the operator name and the reason above."));sessionStorage.setItem("atssc-operator",actor);ui.pending={method,params:{...params,actor,reason,request_id:id(),expected_revision:ui.state.revision}};keepPending();return executePending();}
async function executePending(){const operation=ui.pending;if(!operation||operation.bodyMissing)throw Error(uiText("Recover this operation by its retained ID. Its complete source body remains with the original file."));ui.busy=true;render();try{const result=await call(operation.method,operation.params);clearPending();ui.notice=uiJoin([uiText("Saved "),operation.method.replaceAll("_"," "),uiText(". Original request "),operation.params.request_id]);ui.error=null;await refresh();return result;}catch(e){if(e.definitive)clearPending();throw e;}finally{ui.busy=false;render();}}
async function recoverPending(){if(!ui.pending)return;const p=ui.pending;try{let result;try{result=await call("operation",{request_id:p.params.request_id+(p.method==="dispatch"?":result":"")});}catch(e){if(e.code!=="NOT_FOUND")throw e;if(p.method==="dispatch"){const state=await call("get_message",{id:p.params.id});if(state.message.delivery.state!=="QUEUED"){clearPending();ui.selectedMessage=state.message;ui.notice=uiJoin([uiText("The original dispatch is recorded as "),state.message.delivery.state,uiText(". Provider results continue against this same message.")]);await refresh();return;}}ui.notice=uiText("The original request has not committed. Its same retained body can be retried.");render();return;}clearPending();ui.notice=uiJoin([uiText("Recovered original operation "),result.operation.id,"."]);await refresh();}catch(e){showError(e);}}
async function filePayload(file){if(!file)throw Error(uiText("Choose the complete original file."));if(file.size>64*1024*1024)throw Error(uiText("The original source must fit the application's 64 MiB file limit."));const a=new Uint8Array(await file.arrayBuffer());let text="";for(let i=0;i<a.length;i+=32768)text+=String.fromCharCode(...a.subarray(i,i+32768));return{name:file.name,content_base64:btoa(text)};}
function showError(e){ui.error=errorText(e)+(e?.detail?" · "+j(e.detail):"");render();}
function restoreDrafts(){for(const f of root.querySelectorAll("form[data-form]")){const saved=ui.drafts[f.dataset.form];if(!saved)continue;for(const [name,value]of Object.entries(saved)){const element=f.elements.namedItem(name);if(!element||element.type==="file"||element.type==="password")continue;if(element.type==="checkbox")element.checked=!!value;else if(element.value!==String(value))element.value=value;}}}
function captureDraft(form){if(!form||["login","public-entry","respondent-contact"].includes(form.dataset.form))return;const values={};for(const el of form.elements){if(!el.name||["file","password","submit"].includes(el.type))continue;values[el.name]=el.type==="checkbox"?el.checked:el.value;}ui.drafts[form.dataset.form]=values;}
function attachLanguage(){mountLanguageControl(root.querySelector('header .actions')||root.querySelector('main')||root);}
function render(){if(!ui.session)return;if(!ui.session.authenticated)return renderLogin();if(ui.session.role==="respondent")return renderRespondent();if(!ui.state){root.innerHTML=uiHTML("<main><h1>Opening companies and communications…</h1></main>");return;}const body=views[ui.tab]?.()||views.case();root.innerHTML=uiHTML("<header><div><a href=\"/operator\">Questionnaire Operations</a><h1>Companies and communications</h1><p>")+h(ui.state.profile?.case_reference||"Set up a case")+' · Workspace '+h(ui.state.workspace_id)+'</p></div><div class="actions">'+button(uiText("Refresh"),"refresh")+button(uiText("Sign out"),"logout")+'</div></header><nav aria-label="Operating sections">'+tabs.map(([key,label])=>'<button type="button" data-action="tab" data-id="'+key+'" aria-current="'+(key===ui.tab?"page":"false")+'">'+h(label)+'</button>').join("")+uiHTML("</nav><main><div class=\"operator\"><label>Operator<input id=\"actor\" value=\"")+h(sessionStorage.getItem("atssc-operator")||"")+uiHTML("\" autocomplete=\"name\"></label><label>Reason for the next change<input id=\"reason\" value=\"")+h(ui.reason||"")+uiHTML("\" placeholder=\"Describe the source or operating decision\"></label><span>Edition ")+h(ui.state.revision)+'</span></div>'+(ui.pending?uiHTML("<section class=\"pending\"><h2>Original operation pending</h2><p>")+h(ui.pending.method)+' · '+h(ui.pending.params.request_id)+uiHTML("</p><p>Recover its recorded outcome before another change.</p>")+button(uiText("Recover original operation"),"recover")+button(uiText("Retry same retained request"),"retry","",ui.pending.bodyMissing?"disabled":"")+'</section>':"")+(ui.error?uiHTML("<div role=\"alert\" class=\"notice\"><strong>Review required</strong><p>")+h(ui.error)+'</p></div>':"")+(ui.notice?'<p role="status" class="notice">'+h(ui.notice)+'</p>':"")+body+uiHTML("</main><footer>Original source files, selected company identities and questionnaire records stay together in the saved project.</footer>");restoreDrafts();attachLanguage();if(ui.busy||ui.pending){for(const f of root.querySelectorAll('form[data-mutation] fieldset'))f.disabled=true;for(const b of root.querySelectorAll("[data-mutation-action]"))b.disabled=true;}}
function renderLogin(){root.innerHTML=uiHTML("<main class=\"login\"><a href=\"/operator\">Questionnaire Operations</a><h1>Companies and communications</h1><p>Open the existing operator session using this project’s private access code.</p>")+(ui.error?'<p role="alert">'+h(ui.error)+'</p>':"")+form("login",field(uiText("Operator access code"),"access_code","","password",'required autocomplete="current-password"')+submit(uiText("Open operator session")),false)+'</main>';attachLanguage();}
