handlers.company=async(f,d)=>{const old=ui.company;const sources=[...(old?.sources||[]),...(d.source_reference?[{kind:"OPERATOR_REFERENCE",reference:d.source_reference,at:stamp()}]:[])];await mutate("save_company",{expected_version:old?.id===d.id?old.version:0,company:{id:d.id,name:d.name,aliases:String(d.aliases||"").split(/\r?\n/).map(x=>x.trim()).filter(Boolean),active:bool(d.active),sources,note:d.note}});ui.company=null;delete ui.drafts.company;};
handlers.contact=async(f,d)=>{const company=ui.state.companies.find(c=>c.id===d.company_id);if(!company)throw Error(uiText("Choose an original company."));const old=ui.contact;await mutate("save_contact",{...(old?{id:old.id,expected_version:old.version}:{}),contact:{company_id:company.id,company_name:company.name,contact_name:d.contact_name,email:d.email,phone:d.phone,postal_address:d.postal_address,country:d.country,role:d.role,kind:d.kind,language:d.language,custom:json(d.custom,{}),active:bool(d.active),note:d.note,source:d.source_reference?{kind:"OPERATOR_REFERENCE",reference:d.source_reference,previous:old?.source,at:stamp()}:old?.source}});ui.contact=null;delete ui.drafts.contact;};
handlers["contacts-source"]=async(f,d)=>{ui.contactSource=await call("get_source",{source_id:d.source_id,complete:true});ui.contactChoices=Object.fromEntries((ui.contactSource.contact_links||[]).map(x=>[x.row_id,{action:"KEEP_EXISTING",contact_id:x.contact_id}]));ui.pages["contact-import"]=0;};
handlers["contacts-receive"]=async()=>{const rows=ui.contactSource.report.mapped.rows.map(r=>{const x=ui.contactChoices[r.id]||{};const contact=ui.state.contacts.find(c=>c.id===x.contact_id);return{row_id:r.id,...x,...(contact?{expected_version:contact.version}:{})};});await mutate("receive_contacts",{source_id:ui.contactSource.id,rows});ui.notice=uiText("Every original contact-source row has its saved disposition.");};
handlers.assignments=async(f,d)=>{const assignments=Object.keys(d).filter(k=>k.startsWith("assign.")&&bool(d[k])).map(k=>{const company_id=k.slice(7);return{company_id,contact_id:d["contact."+company_id],publication_id:d.publication_id,...(d.coverage_id?{coverage_id:d.coverage_id}:{})};});if(!assignments.length)throw Error(uiText("Select at least one company and its original contact."));await mutate("assign",{assignments});delete ui.drafts.assignments;};
handlers["assignment-edit"]=async(f,d)=>{const a=ui.selectedAssignment.assignment;await mutate("update_assignment",{id:a.id,expected_version:a.version,assignment:{contact_id:d.contact_id,notice_at:d.notice_at,due_at:d.due_at,registration_state:d.registration_state,active:bool(d.active),paused:bool(d.paused),note:d.note}});ui.selectedAssignment=await call("get_assignment",{id:a.id});delete ui.drafts["assignment-edit"];};
handlers["public-link"]=async(f,d)=>{ui.publicLink=await mutate("save_public_link",{name:d.name,publication_id:d.publication_id,language:d.language,expires_at:d.expires_at});delete ui.drafts["public-link"];};
handlers.template=async(f,d)=>{await mutate("save_template",{...(ui.template?{id:ui.template.id,expected_version:ui.template.version}:{}),template:{name:d.name,kind:d.kind,language:d.language,subject:d.subject,body:d.body}});ui.template=null;delete ui.drafts.template;};
handlers["message-preview"]=async(f,d)=>{ui.messageParams={assignment_id:d.assignment_id,template_id:d.template_id,followup_key:d.followup_key||undefined,at:stamp()};ui.messagePreview=await call("preview_message",ui.messageParams);};
handlers["message-retain"]=async()=>{if(!ui.messagePreview)throw Error(uiText("Review the original complete message first."));const result=await mutate("retain_message",{...ui.messageParams,review_sha256:ui.messagePreview.review_sha256});ui.selectedMessage=result.message;ui.messagePreview=null;};
handlers["delivery-preview"]=async(f,d)=>{const source=await filePayload(f.elements.file.files[0]);ui.deliveryInput={...source,format:d.format,...(d.format==="JSON"?{mapping:json(d.mapping,{})}:{})};ui.delivery=await call("preview_delivery",ui.deliveryInput);};
handlers["delivery-retain"]=async()=>{await mutate("receive_delivery",{...ui.deliveryInput,review_sha256:ui.delivery.review_sha256});if(ui.selectedMessage)ui.selectedMessage=(await call("get_message",{id:ui.selectedMessage.id})).message;ui.delivery=null;};
handlers["followups-read"]=async(f,d)=>{ui.followups=await call("followups",{at:d.at});};
handlers["followup-log"]=async(f,d)=>{await mutate("log_followup",{assignment_id:d.assignment_id,channel:d.channel,outcome:d.outcome,at:d.at,note:d.note,original_source:{kind:"CONTACT_RECORD",reference:d.original_source},...(d.expected_response_at?{expected_response_at:d.expected_response_at}:{})});delete ui.drafts["followup-log"];};
handlers["history-read"]=async(f,d)=>{ui.historyFilter={kind:d.kind,id:d.id};const items=[];let offset=0,total=Infinity;while(offset<total){const page=await call("history",{...ui.historyFilter,offset,limit:500});items.push(...page.items);total=page.total;if(!page.items.length)break;offset+=page.items.length;}ui.history={items,total};};
const actions={
tab:async key=>{ui.tab=key;location.hash=key;ui.error=null;},
refresh:async()=>refresh(),
logout:async()=>{await request("/api/logout",{});ui.session={authenticated:false};ui.state=null;await initializeLanguage(native,ui.session);},
page:async key=>{const[k,p]=key.split("|");ui.pages[k]=Math.max(0,Number(p));},
recover:recoverPending,
retry:async()=>{if(!ui.pending)return;await recoverPending();if(ui.pending&&!ui.pending.bodyMissing)await executePending();},
"contact-bulk-create":async()=>{const linked=new Set((ui.contactSource?.contact_links||[]).map(x=>x.row_id));for(const r of ui.contactSource?.report.mapped.rows||[]){if(r.valid&&!linked.has(r.id)&&!r.warnings.some(w=>w.code==="DUPLICATE_CONTACT_CANDIDATE")&&!ui.contactChoices[r.id]?.action)ui.contactChoices[r.id]={...(ui.contactChoices[r.id]||{}),action:"CREATE",kind:"PERSON"};}ui.notice=uiText("Valid new rows without duplicate candidates are selected for creation. Review remaining rows and differing company names before receiving.");},
"edit-company":async key=>{ui.company=ui.state.companies.find(c=>c.id===key);delete ui.drafts.company;},
"edit-contact":async key=>{ui.contact=ui.state.contacts.find(c=>c.id===key);delete ui.drafts.contact;},
assignment:async key=>{ui.selectedAssignment=await call("get_assignment",{id:key});delete ui.drafts["assignment-edit"];},
"public-link":async key=>{ui.publicLink=await call("get_public_link",{id:key});},
template:async key=>{ui.template=ui.state.templates.find(t=>t.id===key);delete ui.drafts.template;},
"install-templates":async()=>mutate("install_templates",{}),
"sync-notifications":async()=>{const result=await mutate("sync_notifications",{at:stamp()});ui.notice=uiJoin([uiText("Prepared "),result.messages.length,uiText(" original response notices; "),result.skipped.length,uiText(" require contact or template review.")]);if(result.skipped.length)ui.error=j(result.skipped);},
message:async key=>{ui.selectedMessage=(await call("get_message",{id:key})).message;},
dispatch:async key=>{const result=await mutate("dispatch",{id:key});ui.selectedMessage=(await call("get_message",{id:key})).message;ui.notice=uiJoin([uiText("Original provider outcome: "),result.delivery?.state||ui.selectedMessage.delivery.state,"."]);},
"cancel-message":async key=>{const message=(await call("get_message",{id:key})).message;await mutate("cancel_message",{id:key,expected_version:message.version});ui.selectedMessage=(await call("get_message",{id:key})).message;},
"record-unknown":async key=>{await mutate("record_unknown",{id:key});ui.selectedMessage=(await call("get_message",{id:key})).message;},
"process-due":async key=>{const result=await mutate("process_due",{send:key==="send"});ui.notice=uiJoin([uiText("Configured follow-up job completed. "),j(result.job)]);ui.followups=await call("followups",{at:stamp()});},
"prepare-followup":async key=>{const item=ui.followups.items.find(x=>x.key===key);const a=ui.state.assignments.find(x=>x.id===item.assignment_id);ui.messageParams={assignment_id:a.id,template_id:"standard-reminder-"+a.language.toLowerCase(),followup_key:key,at:stamp()};ui.messagePreview=await call("preview_message",ui.messageParams);delete ui.drafts["message-preview"];ui.tab="messages";},
"open-public-response":async()=>{const result=ui.publicResult;await request("/api/session",{role:"respondent",respondent_id:result.respondent_id,access_code:result.access_code});location.assign(result.entry_path);}
};
function contactFields(c={},language="EN",company=true){const fr=getLanguage()==="FR";return(company?field((fr?uiText("Entreprise"):uiText("Company")),"company_name",c.company_name,"text","required"):"")+field((fr?uiText("Nom de la personne-ressource"):uiText("Contact name")),"contact_name",c.contact_name,"text","required")+field((fr?uiText("Courriel"):uiText("Email")),"email",c.email,"email")+field((fr?uiText("Téléphone"):uiText("Phone")),"phone",c.phone)+area((fr?uiText("Adresse postale"):uiText("Postal address")),"postal_address",c.postal_address)+field((fr?uiText("Pays"):uiText("Country")),"country",c.country)+select((fr?uiText("Langue"):uiText("Language")),"language",[{value:"EN",label:uiText("English")},{value:"FR",label:uiText("Français")}],c.language||language);}
function renderPublic(){const p=ui.publicInfo,fr=getLanguage()==="FR";root.innerHTML='<main class="public-entry"><h1>'+h(p.questionnaire_title)+'</h1><p>'+h(p.organization_name)+' · '+h(p.case_reference)+'</p><p>'+h(p.case_title)+'</p><p>'+h((fr?uiText("Date limite : "):uiText("Response due: ")))+h(p.due_at)+'</p>'+(ui.error?'<p class="notice" role="alert">'+h(ui.error)+'</p>':"")+(ui.publicResult?'<h2>'+h((fr?uiText("Votre accès au questionnaire"):uiText("Your questionnaire access")))+'</h2><p>'+h(ui.publicResult.company_name)+'</p><p>'+h((fr?uiText("Code d’accès privé : "):uiText("Private access code: ")))+'<strong>'+h(ui.publicResult.access_code)+'</strong></p>'+button((fr?uiText("Ouvrir votre questionnaire"):uiText("Open your questionnaire")),"open-public-response"):'<p>'+h((fr?uiText("Saisissez les coordonnées de votre entreprise. Elles seront examinées par le personnel responsable du questionnaire."):uiText("Enter your company’s contact information. Staff will review it with the original questionnaire assignment.")))+'</p>'+form("public-entry",contactFields({},p.language)+submit((fr?uiText("Créer mon accès"):uiText("Create my access"))),false))+'<p>'+h((fr?uiText("Assistance : "):uiText("For assistance: ")))+h(p.support_contact)+'</p></main>';attachLanguage();}
async function renderRespondent(){if(!ui.respondentContact){try{ui.respondentContact=await call("respondent_contact",{respondent_id:ui.session.respondent_id});}catch(e){root.innerHTML=uiHTML("<main><h1>Contact information</h1><p>")+h(errorText(e))+'</p><a href="/respondent/'+h(ui.session.respondent_id)+uiHTML("\">Return to your questionnaire</a></main>");attachLanguage();return;}}const value=ui.respondentContact,fr=getLanguage()==="FR";root.innerHTML='<main class="public-entry"><h1>'+h((fr?uiText("Vos coordonnées"):uiText("Your contact information")))+'</h1><p>'+h(value.contact.company_name)+'</p><a href="/respondent/'+h(ui.session.respondent_id)+'">'+h((fr?uiText("Retourner au questionnaire"):uiText("Return to your questionnaire")))+'</a>'+(ui.error?'<p role="alert" class="notice">'+h(ui.error)+'</p>':"")+(ui.notice?'<p role="status">'+h(ui.notice)+'</p>':"")+form("respondent-contact",contactFields(value.contact,value.contact.language,false)+submit((fr?uiText("Enregistrer les coordonnées"):uiText("Save contact information"))),false)+'</main>';attachLanguage();}
handlers["public-entry"]=async(f,d)=>{if(!ui.publicRequest)ui.publicRequest={token:ui.publicToken,request_id:id(),contact:{...d,kind:"PUBLIC_ENTRY"}};const response=await request("/api/outreach/public-entry",ui.publicRequest);ui.publicResult=response.result;ui.error=null;renderPublic();};
handlers["respondent-contact"]=async(f,d)=>{const old=ui.respondentContact;if(!ui.respondentRequest)ui.respondentRequest={respondent_id:ui.session.respondent_id,expected_version:old.version,request_id:id(),contact:{contact_name:d.contact_name,email:d.email,phone:d.phone,postal_address:d.postal_address,country:d.country,language:d.language}};await call("update_respondent_contact",ui.respondentRequest);ui.respondentRequest=null;ui.respondentContact=await call("respondent_contact",{respondent_id:ui.session.respondent_id});ui.notice=(ui.respondentContact.contact.language==="FR"?uiText("Coordonnées enregistrées."):uiText("Contact information saved."));};
root.addEventListener("input",event=>{const el=event.target;if(el.id==="reason")ui.reason=el.value;if(el.id==="actor")sessionStorage.setItem("atssc-operator",el.value);if(el.dataset.choice){const row=el.dataset.row;ui.contactChoices[row]={...(ui.contactChoices[row]||{}),[el.dataset.choice]:el.value};}captureDraft(el.closest("form"));});
root.addEventListener("change",event=>{const el=event.target;if(el.dataset.choice){const row=el.dataset.row;ui.contactChoices[row]={...(ui.contactChoices[row]||{}),[el.dataset.choice]:el.value};}captureDraft(el.closest("form"));});
root.addEventListener("submit",async event=>{const f=event.target.closest("form[data-form]");if(!f)return;event.preventDefault();if(f.dataset.submitting==='true')return;const method=handlers[f.dataset.form];if(!method)return;captureDraft(f);f.dataset.submitting='true';for(const b of f.querySelectorAll('button[type=submit]'))b.disabled=true;ui.error=null;const data=Object.fromEntries(new FormData(f));try{await method(f,data);}catch(e){ui.error=errorText(e)+(e?.detail?" · "+j(e.detail):"");if(f.dataset.form==="public-entry"&&e.definitive)ui.publicRequest=null;if(f.dataset.form==="respondent-contact"&&e.definitive)ui.respondentRequest=null;}finally{delete f.dataset.submitting;if(ui.publicInfo)renderPublic();else render();}});
root.addEventListener("click",async event=>{const b=event.target.closest("[data-action]");if(!b||b.disabled)return;const run=actions[b.dataset.action];if(!run)return;b.disabled=true;try{ui.error=null;await run(b.dataset.id);}catch(e){showError(e);}finally{if(ui.publicInfo)renderPublic();else render();}});
window.addEventListener("hashchange",()=>{const tab=location.hash.slice(1);if(tabs.some(x=>x[0]===tab)){ui.tab=tab;render();}});
async function boot(){try{if(location.pathname.startsWith("/public/entry/")){ui.publicToken=decodeURIComponent(location.pathname.slice("/public/entry/".length));ui.publicInfo=await request("/api/outreach/public?token="+encodeURIComponent(ui.publicToken));setLanguage(ui.publicInfo.language==='FR'?'FR':getLanguage());renderPublic();return;}ui.tab=tabs.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):"case";ui.session=await request("/api/session");await initializeLanguage(native,ui.session);if(ui.session.authenticated&&ui.session.role==="operator"){await refresh();try{ui.pending=JSON.parse(sessionStorage.getItem(pendingKey())||"null");}catch{}}render();}catch(e){root.innerHTML=uiHTML("<main><h1>Companies and communications</h1><p role=\"alert\">")+h(errorText(e))+'</p>'+button(uiText("Reload"),"reload")+'</main>';}}
actions.reload=async()=>location.reload();
boot();
